"""Class 7 Maths Ch 2 - Arithmetic Expressions."""
import re
from g67 import *

SLUG, NAME, CHNO = "Arithmetic_Expressions", "Arithmetic Expressions", 2

def ev(e):
    return eval(re.sub(r"(\d+)", r"Fr(\1)", e))
def tx(e): return "$" + e.replace("*", "\\times ").replace("/", "\\div ") + "$"
def val(e):
    v = ev(e); assert v.denominator == 1, e; return int(v)
def ex(q, e, why="Apply BODMAS: brackets, orders, division/multiplication, addition/subtraction.", offs=(1, -1, 2, -2, 10, 3, -10)):
    v = val(e)
    return nm(q.format(tx(e)), v, why, offs, pos=False)
def exq(q, e, *steps):
    return QQ(q.format(tx(e)), *steps, f"Value $={val(e)}$")
def ok(e):
    try: return ev(e).denominator == 1
    except Exception: return False
def L(xs): return ", ".join(map(str, xs))

